<script setup lang="ts">
import { ref, onMounted } from 'vue';
import { Plus, Monitor, UserRoundCog, ShieldCheck, Copy } from 'lucide-vue-next';
import { api, send, user } from '../api';
import Modal from '../components/Modal.vue';
const users = ref<any[]>([]), kiosks = ref<any[]>([]), system = ref<any>(null), error = ref(''), message = ref(''), busy = ref(false), showUser = ref(false), showKiosk = ref(false), newToken = ref(''), kioskName = ref('');
const form = ref({ name: '', email: '', password: '', role: 'HR' });
async function load() { if (user.value?.role !== 'ADMIN') return; try { [users.value, kiosks.value, system.value] = await Promise.all([api('/users'), api('/kiosks'), api('/system')]); } catch (e) { error.value = (e as Error).message; } } onMounted(load);
async function saveUser() { busy.value = true; error.value = ''; try { await api('/users', send('POST', form.value)); form.value = { name: '', email: '', password: '', role: 'HR' }; showUser.value = false; message.value = 'Account created.'; await load(); } catch (e) { error.value = (e as Error).message; } finally { busy.value = false; } }
async function toggle(u: any) { busy.value = true; error.value = ''; try { await api(`/users/${u.id}`, send('PATCH', { active: !u.active })); await load(); } catch (e) { error.value = (e as Error).message; } finally { busy.value = false; } }
async function createKiosk() { busy.value = true; error.value = ''; try { const result = await api('/kiosks', send('POST', { name: kioskName.value })); newToken.value = result.token; await load(); } catch (e) { error.value = (e as Error).message; } finally { busy.value = false; } }
async function revoke(k: any) { busy.value = true; error.value = ''; try { await api(`/kiosks/${k.id}`, send('DELETE')); await load(); } catch (e) { error.value = (e as Error).message; } finally { busy.value = false; } }
async function copy() { try { await navigator.clipboard.writeText(newToken.value); message.value = 'Kiosk token copied.'; } catch { error.value = 'Clipboard unavailable. Select and copy the token manually.'; } }
</script>
<template><div v-if="user?.role !== 'ADMIN'" class="panel empty-state"><ShieldCheck :size="32" /><h3>Administrator access required</h3><p>Contact your system administrator to manage accounts and devices.</p></div><template v-else><p v-if="message" class="alert success" role="status">{{ message }}</p><p v-if="error && !showUser && !showKiosk" class="alert error" role="alert">{{ error }}</p><div class="alert info"><ShieldCheck :size="20" /><span>Face service: <strong>{{ system?.ai?.ready ? 'Ready' : 'Unavailable or model not configured' }}</strong>. {{ system?.ai?.liveness ? 'Liveness enabled.' : 'Anti-spoofing has not been validated for this release.' }}</span></div><section class="panel"><div class="panel-heading"><div><h2>Administrative accounts</h2><p>Admins manage accounts; HR manages records; auditors have read access.</p></div><button class="button primary" @click="showUser = true; error = ''"><Plus :size="17" /> Add account</button></div><div class="table-wrap"><table><thead><tr><th>Person</th><th>Role</th><th>Status</th><th>Action</th></tr></thead><tbody><tr v-for="u in users" :key="u.id"><td><strong class="cell-title">{{ u.name }}</strong><small class="cell-subtitle">{{ u.email }}</small></td><td><span class="badge neutral">{{ u.role }}</span></td><td><span :class="['badge', u.active ? 'green' : 'neutral']">{{ u.active ? 'Active' : 'Disabled' }}</span></td><td><button v-if="u.id !== user.id" class="text-button" :disabled="busy" @click="toggle(u)">{{ u.active ? 'Disable account' : 'Enable account' }}</button><span v-else class="muted small-text">Your account</span></td></tr></tbody></table></div></section><section class="panel settings-kiosks"><div class="panel-heading"><div><h2>Kiosk devices</h2><p>Pair each kiosk with a separate, revocable device token.</p></div><button class="button secondary" @click="showKiosk = true; newToken = ''; kioskName = ''; error = ''"><Plus :size="17" /> Register kiosk</button></div><div v-if="!kiosks.length" class="empty-state compact"><Monitor :size="30" /><h3>No kiosks registered</h3><p>Create a token and enter it on the attendance kiosk.</p></div><div v-else class="table-wrap"><table><thead><tr><th>Device</th><th>Status</th><th>Action</th></tr></thead><tbody><tr v-for="k in kiosks" :key="k.id"><td>{{ k.name }}</td><td><span :class="['badge', k.active ? 'green' : 'neutral']">{{ k.active ? 'Active' : 'Revoked' }}</span></td><td><button v-if="k.active" class="text-button destructive" :disabled="busy" @click="revoke(k)">Revoke token</button></td></tr></tbody></table></div></section></template><Modal v-if="showUser" title="Create account" @close="!busy && (showUser = false)"><form @submit.prevent="saveUser"><p v-if="error" class="alert error" role="alert">{{ error }}</p><label>Full name<input v-model="form.name" required maxlength="120" /></label><label>Email<input v-model="form.email" type="email" required maxlength="254" autocomplete="off" /></label><label>Password (at least 12 characters)<input v-model="form.password" type="password" minlength="12" maxlength="128" autocomplete="new-password" required /></label><label>Role<select v-model="form.role"><option value="HR">HR officer</option><option value="AUDITOR">Auditor</option><option value="ADMIN">Administrator</option></select></label><div class="modal-actions"><button type="button" class="button secondary" :disabled="busy" @click="showUser = false">Cancel</button><button class="button primary" :disabled="busy">{{ busy ? 'Saving…' : 'Create account' }}</button></div></form></Modal><Modal v-if="showKiosk" title="Register a kiosk" @close="!busy && (showKiosk = false)"><p v-if="error" class="alert error" role="alert">{{ error }}</p><div v-if="newToken"><p class="alert info">Copy this token now. It is shown once. Enter it on the kiosk device; keep it private.</p><label>Device token<textarea readonly :value="newToken" rows="3" class="token-field" /></label><button class="button secondary" @click="copy"><Copy :size="16" /> Copy token</button><RouterLink to="/kiosk" class="button primary" @click="showKiosk = false; newToken = ''">Open kiosk</RouterLink></div><form v-else @submit.prevent="createKiosk"><label>Device name<input v-model="kioskName" required maxlength="120" placeholder="Municipal hall entrance" /></label><div class="modal-actions"><button type="button" class="button secondary" :disabled="busy" @click="showKiosk = false">Cancel</button><button class="button primary" :disabled="busy">{{ busy ? 'Creating…' : 'Create device token' }}</button></div></form></Modal></template>
